"""A source-attributed plugin comparison visitors can use without an account."""
import json

CLIP = 'https://www.tiktok.com/@chase_ai_/video/7709026892858363150'


def apply_comparison(base, dist, pages):
    presets = {
        'website-superpowers': dict(task='Cabin rental website from the same client brief', plugin='Superpowers', criterion='Client wishes met on the first pass (%)', baselineCost=2.84, pluginCost=5.15, baselineTime=14, pluginTime=26, baselineQuality=63, pluginQuality=100, note='Chase AI reported results · website slide at 06:15 · reviewed 21 Nov 2026. Plain reached 100% after fixes. One build per condition; not independently reproduced.', source=CLIP),
        'website-ecc': dict(task='Cabin rental website from the same client brief', plugin='ECC', criterion='Client wishes met on the first pass (%)', baselineCost=2.84, pluginCost=8.66, baselineTime=14, pluginTime=39, baselineQuality=63, pluginQuality=100, note='Chase AI reported results · website slide at 06:15 · reviewed 21 Nov 2026. Plain reached 100% after fixes. One build per condition; not independently reproduced.', source=CLIP),
        'motion': dict(task='Synthetic practice reservation form: baseline versus Motion Design guidance', plugin='Motion Design guidance', criterion='Recorded browser acceptance checks passed (%)', baselineCost=None, pluginCost=None, baselineTime=None, pluginTime=None, baselineQuality=100, pluginQuality=100, note='SkillLantern independent pair · 9 Nov 2026 · 13/13 recorded browser checks passed for each output. One generated output per condition. Generation cost/time unmeasured; not a first-pass requirements score. Native installation not exercised.', source='{{root}}evidence/motion-results.json'),
        'own': dict(task='', plugin='', criterion='Acceptance checks passed (%)', baselineCost=None, pluginCost=None, baselineTime=None, pluginTime=None, baselineQuality=None, pluginQuality=None, note='Your own comparison. Keep the task, project snapshot, model, effort and acceptance checks the same. Use fresh isolated sessions. Include setup/background costs and human fixes; repeat when affordable.', source='')
    }
    def external(url, label):
        return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{label}</a>'
    cases = [
        ('Superpowers', 'obra/superpowers', '04:07–06:35', 'A planning and development workflow.', 'Coding job 2: $0.32 → $0.37, but 7.6 → 5.1 min. Website: $2.84 → $5.15; 14 → 26 min.', 'Website first-pass wishes met: 63% → 100%. Final hidden-test scores: 100 → 100. The creator reported higher first-pass coverage with the higher spend.'),
        ('Caveman', 'JuliusBrussee/caveman', '06:35–08:05', 'Shorter answers and tool output.', '20 developer questions, each answered twice: $0.152 → $0.162 per answer; answer score 94.3 → 94.1 / 100.', 'The “answer concisely” control cost $0.113, with a lower 90.1 score. Shorter output alone did not establish better value. Today’s repository also includes a proxy; the clip tested a particular skill setup.'),
        ('Graphify', 'Graphify-Labs/graphify', '08:09–10:23', 'A queryable codebase knowledge graph.', 'Textual session: $4.63 → $5.74; 12-question time 12.7 → 16.5 min; answer score 93.0 → 89.1 / 100.', 'Reported tokens read per question: 258K → 288K. Local mapping and Cloud are distinct; this test does not settle the Cloud service’s claims.'),
        ('Claude-Mem', 'thedotmack/claude-mem', '10:24–12:10', 'Persistent session context and retrieval.', 'Built-in memory → built-in plus Claude-Mem: $5.50 → $5.54 total. Scenario scores were equal: 1.00, 0.75, 1.00 on both sides (scale 0–1).', 'Three scenarios across three sessions. Equal scores include imperfect recall of a changed decision; they do not establish perfect memory or universal redundancy.'),
        ('ECC', 'affaan-m/ecc', '12:11–13:49', 'An agent harness and workflow configuration.', 'Coding job 2: $0.32 → $1.22, but 7.6 → 6.5 min. Website: $2.84 → $8.66; 14 → 39 min.', 'Website first-pass wishes met: 63% → 100%; final hidden-test scores: 100 → 99.4. Startup context: 23.8K → 52.8K tokens in the creator’s configuration.')
    ]
    case_html = ''.join(f'<article class="pc-case"><div class="pc-case-heading"><h3>{name}</h3><span>{time}</span></div><p class="small">{purpose}</p><p>{numbers}</p><details><summary>What this result leaves open</summary><p>{limit}</p></details><div class="pc-source-links">{external("https://github.com/"+repo,"Original project")} {external(CLIP,"Clip · "+time)}</div></article>' for name,repo,time,purpose,numbers,limit in cases)
    columns = ''
    for side, title, sub in [('baseline', 'A · Plain baseline', 'Same task, your usual necessary instructions'), ('plugin', 'B · With one extension', 'Same task, add only the capability being tested')]:
        fields = ''
        for key,label in [('cost','Cost (USD)'),('time','Elapsed time (minutes)'),('quality','Criterion met (%)')]:
            maximum = 'max="100"' if key == 'quality' else ''
            fields += f'<label for="{side}-{key}">{label}<input id="{side}-{key}" type="number" min="0" {maximum} step="any" inputmode="decimal" data-measurement autocomplete="off"></label>'
        columns += f'<fieldset class="pc-condition"><legend>{title}</legend><p class="small">{sub}</p>{fields}</fieldset>'
    body = '''<link rel="stylesheet" href="{{root}}assets/chase_compare.css"><script defer src="{{root}}assets/chase_compare.js"></script>
<div class="plugin-comparison"><a class="back-link" href="{{root}}popular.html">← Popular &amp; discovery</a>
<header class="pc-hero"><div><p class="eyebrow">A better question before you install</p><h1>Is this plugin<br>worth adding?</h1><p class="lede">Compare the same task with and without it. Cost, time and a useful result belong in the same decision.</p><a class="button" href="#try-comparison">Try the comparison ↓</a></div><aside class="pc-hero-note"><span class="pc-mark" aria-hidden="true">A / B</span><p>Higher cost.<br>Better first pass.<br><strong>Both can be true.</strong></p><span class="small">One website example from Chase AI, unpacked below.</span></aside></header>
<section class="pc-section" aria-labelledby="website-title"><div class="pc-section-head"><p class="eyebrow">The example that needs a closer look</p><h2 id="website-title">Same brief. A real tradeoff.</h2><p>Chase AI’s cabin-rental website comparison reports higher cost and time with both extensions—and better first-pass requirement coverage.</p></div><div class="pc-table-scroll" tabindex="0" role="region" aria-label="Creator-reported website comparison"><table class="pc-table"><caption>Creator-reported website results · slide at 06:15 · one build each</caption><thead><tr><th scope="col">Measure</th><th scope="col">Plain Claude Code</th><th scope="col">Superpowers</th><th scope="col">ECC</th></tr></thead><tbody><tr><th scope="row">Cost</th><td>$2.84</td><td>$5.15</td><td>$8.66</td></tr><tr><th scope="row">Time</th><td>14 min</td><td>26 min</td><td>39 min</td></tr><tr class="pc-highlight"><th scope="row">Client wishes met, first pass</th><td>63%</td><td>100%</td><td>100%</td></tr><tr><th scope="row">Client wishes met, after fixes</th><td>100%</td><td>100% initially</td><td>100% initially</td></tr><tr><th scope="row">Hidden-test score</th><td>100</td><td>100</td><td>99.4</td></tr><tr><th scope="row">Code review / 5</th><td>3.25</td><td>4</td><td>4.25</td></tr><tr><th scope="row">Design review / 5</th><td>3.75</td><td>4</td><td>4</td></tr></tbody></table></div><p class="small">The creator’s scores and dollar figures are reported evidence, not our reproduction or a subscription invoice. Similar final tests do not make first-pass quality identical.</p></section>
<section id="try-comparison" class="pc-workbench" aria-labelledby="compare-title"><div class="pc-section-head"><p class="eyebrow">Make the comparison useful to you</p><h2 id="compare-title">One task. Two conditions.</h2><p>Start with an attributed example, or clear the form for your own task. Leave unmeasured fields blank; zero means measured zero.</p></div><noscript><p>The examples and sources work without JavaScript. Enable JavaScript to calculate and export your comparison.</p></noscript><form id="comparison-form" novalidate><label for="comparison-preset">Load a comparison<select id="comparison-preset"><option value="website-superpowers">Chase AI · website / Superpowers</option><option value="website-ecc">Chase AI · website / ECC</option><option value="motion">SkillLantern · independent Motion Design pair</option><option value="own">My own task · blank comparison</option></select></label><div class="pc-provenance"><p id="comparison-provenance"></p><a id="comparison-source" href="''' + CLIP + '''">Inspect this example’s source</a></div><div class="pc-task-fields"><label for="comparison-task">Task<input id="comparison-task" type="text" maxlength="300" autocomplete="off"></label><label for="comparison-plugin">Extension being tested<input id="comparison-plugin" type="text" maxlength="150" autocomplete="off"></label><label class="pc-full" for="comparison-criterion">What counts as a useful result?<input id="comparison-criterion" type="text" maxlength="300" autocomplete="off"></label></div><div class="pc-conditions">''' + columns + '''</div><p class="small">Use the same currency and measurement method on both sides. Criterion percentages must use the same checks; 100% means all checks met. Count setup, background work and fixes consistently. Cost estimates and billed totals are different measures.</p><label for="comparison-notes">Context &amp; corrections (optional)<textarea id="comparison-notes" rows="2" maxlength="2000" aria-describedby="comparison-privacy"></textarea></label><p class="small" id="comparison-privacy">No secrets needed. Entries stay in this page’s memory; nothing is submitted or saved. Copy or download before leaving.</p></form><section id="comparison-results" class="pc-results" aria-live="polite" aria-atomic="true" aria-label="Comparison results"><div id="cost-result"></div><div id="time-result"></div><div id="quality-result"></div></section><p id="comparison-reading" class="pc-reading"></p><div class="pc-actions"><button class="button" type="button" id="copy-comparison">Copy comparison</button><button class="button secondary" type="button" id="download-comparison">Download .md</button><span id="comparison-export-status" role="status"></span></div><details class="pc-export"><summary>View the text to copy manually</summary><textarea id="comparison-export" rows="12" readonly aria-label="Comparison Markdown export"></textarea></details></section>
<section class="pc-section" aria-labelledby="five-title"><div class="pc-section-head"><p class="eyebrow">Five extensions, different promises</p><h2 id="five-title">What the clip actually compared.</h2><p>Plain → extension in each example below. These are the creator’s reported observations in his configuration, not universal costs or a ranking.</p></div><div class="pc-cases">''' + case_html + '''</div></section>
<section class="pc-independent"><div><p class="eyebrow">Separate evidence · SkillLantern · 9 Nov 2026</p><h2>Our Motion pair is inspectable.</h2><p>One synthetic reservation form, one output per condition. Both passed all 13 recorded browser checks, including validation, retry, keyboard flow, reduced motion and mobile layout. Generation cost and time were not measured.</p><p class="small">No human preference study, screen-reader or physical-device benchmark. Native skill installation was not exercised. Passing these checks does not establish a design-quality improvement.</p><button class="button secondary" id="load-motion" type="button">Load our pair in the comparison</button></div><div class="pc-independent-links"><a href="{{root}}demos/motion/baseline.html">Open baseline demo ↗</a><a href="{{root}}demos/motion/candidate.html">Open guided demo ↗</a><a href="{{root}}evidence/motion-results.json">Inspect recorded browser checks ↗</a><a href="{{root}}comparisons.html">Read the paired comparison ↗</a></div></section>
<section class="pc-section pc-method"><h2>Run a fair comparison of your own.</h2><ol><li><strong>Choose a bounded task.</strong> Write acceptance checks before either run; use a disposable copy of the same project snapshot.</li><li><strong>Hold the setup steady.</strong> Same model, version, effort, permissions and necessary project rules. Fresh isolated sessions; change one optional extension.</li><li><strong>Measure the whole job.</strong> Include startup context, setup/background costs, elapsed time, first-pass coverage and human corrections. Repeat runs when affordable.</li><li><strong>Choose for your actual constraints.</strong> A faster or better first pass can justify extra cost. A tie on one task cannot settle every future task.</li></ol></section>
<details class="pc-coverage"><summary>Sources, coverage &amp; limits · reviewed 21 Nov 2026</summary><p>Inspired by ''' + external(CLIP, 'Chase AI’s 18-minute TikTok comparison') + ''' (metadata upload date: 17 Nov 2026). We reviewed the full supplied captions and 24 sampled frames; no continuous watch or listening, and no benchmark reproduction. Website numbers above were checked against the 06:15 slide. Caption errors are possible; the slide reports 1,500 Textual files.</p><p>Original project links were checked 21 Nov 2026. Repositories can change after the version in the clip. No raw prompts, pinned versions, full run logs, grading rubrics or complete diffs were available; score calibration, dollar accounting and statistical confidence are unknown. The creator promotes a paid masterclass, which we did not assess.</p><p>Anthropic’s ''' + external('https://code.claude.com/docs/en/costs', 'cost guidance') + ''' supports inspecting context and configuration. Useful skills and hooks can still help; this page does not infer that every extension should be removed. Built-in memory is documented in ''' + external('https://code.claude.com/docs/en/memory', 'Claude Code’s memory guide') + '''.</p></details></div><script type="application/json" id="comparison-presets">''' + json.dumps(presets).replace('<', '\\u003c') + '</script>'
    path = 'guides/plugin-worth-it.html'
    pages[path] = dict(path=path, title='Is this plugin worth adding? Compare cost, time and results', description='Compare AI extensions on the same task. Explore Chase AI’s reported examples, inspect our Motion pair, and calculate your own cost, time and quality tradeoff.', body=body, activeNav='guides')
    promo = '<aside class="pc-promo" style="padding:22px;border:1px solid #c7d3c7;border-radius:12px;margin:24px 0;background:#edf1e9"><p class="eyebrow">Before adding another extension</p><h2 style="font-size:26px;margin:8px 0">Is this plugin worth adding?</h2><p>Compare cost, time and first-pass results on the same task. Start with a real example, then try your own.</p><a href="{{root}}guides/plugin-worth-it.html">Open the interactive comparison →</a></aside>'
    for target in ('index.html', 'guides.html', 'popular.html', 'capabilities/motion-design.html'):
        if target in pages:
            if target == 'index.html':
                pages[target]['body'] = pages[target]['body'].replace('<section class="example-shelf">', promo+'<section class="example-shelf">', 1)
            else:
                pages[target]['body'] += promo
    for filename in ('chase_compare.css', 'chase_compare.js'):
        (dist/'assets'/filename).write_text((base/filename).read_text(encoding='utf-8'), encoding='utf-8')
